('posts','seed01',$j${"pin": "geisel", "headline": "Named after a children’s book author", "tags": ["history"], "text": "Geisel Library is named after Theodor Seuss Geisel, better known as Dr. Seuss. He and his wife Audrey lived in La Jolla. There’s a statue of him with the Cat in the Hat nearby, and once you know it’s there you can’t stop noticing it.", "teaser": "text", "by": "seed", "byName": "JohnDoe458", "at": 1789800000000}$j$::jsonb),
('posts','seed02',$j${"pin": "geisel", "headline": "24 hours on the 2nd floor", "tags": ["heartfelt", "advice"], "text": "I stayed here for over 24 hours during my first finals week because I was too embarrassed to tell anyone I was behind. Around 3am a stranger at my table slid half a granola bar over without saying anything. We studied in silence until sunrise. I never got her name, but I started going to office hours after that.", "teaser": "text", "by": "seed", "byName": "JaneDoe27", "at": 1792000000000}$j$::jsonb),
('posts','seed03',$j${"pin": "geisel", "headline": "The 8th floor at sunset", "tags": ["heartfelt", "hidden"], "text": "When everything felt like too much, I’d take the elevator to the 8th floor right before sunset. You can see the ocean from up there, all the way past the eucalyptus trees. I’d give myself ten minutes to just watch the sky change color before going back to my problem sets. It sounds small, but it made the hardest quarter feel survivable.", "teaser": "photo", "by": "seed", "byName": "tiffanie", "at": 1794100000000, "photos": ["data:image/jpeg;base64,"]}$j$::jsonb),
('posts','seed04',$j${"pin": "coraltree", "headline": "The tree that blooms naked", "tags": ["nature", "hidden"], "text": "This tree is completely bare in winter. Then the coral-red flowers show up before a single leaf does, which is where the “naked” comes from. Coral trees are in the genus Erythrina, from the Greek word for red. Hummingbirds go wild for it in spring.", "teaser": "text", "by": "seed", "byName": "PlantNerd", "at": 1793500000000}$j$::jsonb),
('posts','seed05',$j${"pin": "coraltree", "headline": "Where I said yes", "tags": ["heartfelt", "firsts"], "text": "My partner and I met in a lab section freshman year. Three years later, in spring, they asked me to meet them here “to look at the flowers.” I didn’t understand why they were so nervous until they got down on one knee. Every spring when it blooms, we come back.", "teaser": "text", "by": "seed", "byName": "Joe", "at": 1793600000000}$j$::jsonb),
('posts','seed06',$j${"pin": "dirtybirds", "headline": "The wings that started a tradition", "tags": ["funny", "firsts"], "text": "After I bombed my first chem midterm, my roommate dragged me here and said we’re not talking about it until the wings are gone. By the end, I was laughing about it. Now every Thursday is wing night, midterm or not. Go before 6 or the line gets long.", "teaser": "text", "by": "seed", "byName": "Joe", "at": 1793700000000}$j$::jsonb),
('posts','seed07',$j${"pin": "hammocks", "headline": "Nap spot strategy", "tags": ["advice", "funny"], "text": "The shady hammocks are always taken by 11. The sunny ones open up around noon when people leave for lunch. Bring a sweatshirt to use as a pillow and set an alarm, because I have slept through a discussion section here. Twice.", "teaser": "text", "by": "seed", "byName": "JaneDoe27", "at": 1793800000000}$j$::jsonb),
('posts','seed08',$j${"pin": "fountain", "headline": "The coldest water on campus", "tags": ["advice", "hidden"], "text": "This one has a bottle filler and it’s in the shade, so the water actually stays cold. It’s my last stop before the long walk down to the beach. Someone taped a tiny smiley face sticker on the side years ago and nobody has ever taken it off.", "teaser": "text", "by": "seed", "byName": "Joe", "at": 1793900000000}$j$::jsonb),
('posts','seed09',$j${"pin": "sungod", "headline": "A bird that became a festival", "tags": ["history"], "text": "Sun God was made by artist Niki de Saint Phalle and was the first piece in the Stuart Collection. Students loved it so much that the spring festival is named after it. People dress it up for big moments, so look for a graduation cap in June.", "teaser": "text", "by": "seed", "byName": "JohnDoe458", "at": 1794000000000}$j$::jsonb),
('posts','seed10',$j${"pin": "sungod", "headline": "The day I almost transferred", "tags": ["heartfelt"], "text": "I was sitting under Sun God with my transfer application open on my laptop, ready to hit submit. A senior sat down and asked what I was working on. I told her I didn’t feel like I belonged here. She said she felt the exact same way her first year, and that it gets better once you find your people. I closed the laptop. I found my people a month later.", "teaser": "text", "by": "seed", "byName": "PlantNerd", "at": 1794150000000}$j$::jsonb),
('replies','seedr1',$j${"post": "seed02", "text": "This made me tear up. Going to office hours tomorrow.", "by": "seed", "byName": "tiffanie", "at": 1792500000000}$j$::jsonb)
